<script setup lang="ts">
import { ArrowRight, Check, Copy, MapPin, Package, Phone, X } from '@lucide/vue';
import { WEB_ORDER_OPERATOR_ROLES, webOrderNextStatuses } from '~/shared/web-order-actions';
import { warehouseExecution, warehouseFactAt, warehouseNumber, warehouseStatusLabel, warehouseTotal } from '~/shared/warehouse-execution';
const selected = useState<any | null>('admin-order-selected', () => null); const copied = ref(false);
const config = useRuntimeConfig();
const route = useRoute(), isCrmOrder = computed(() => route.path.startsWith('/crm/'));
const session = useWorkspaceSession();
const access = useWorkspaceAccess();
const savedOrder = useState<any>('admin-order-saved', () => null);
const statusDraft = ref('');
const saving = ref(false);
const actionError = ref('');
const canManage = computed(() => access.ready.value && WEB_ORDER_OPERATOR_ROLES.includes(session.user.value?.role || '') && access.can('web_orders.write'));
const nextStatuses = computed(() => canManage.value ? webOrderNextStatuses(selected.value) : []);
watch(() => `${selected.value?.id || ''}:${session.token.value}`, () => { statusDraft.value = ''; actionError.value = ''; });
async function saveStatus() {
  if (saving.value || !selected.value || !nextStatuses.value.includes(statusDraft.value) || !session.token.value) return;
  const order = selected.value, token = session.token.value, target = statusDraft.value;
  if (target === 'CANCELLED' && !confirm('Отменить неоплаченный заказ? Доступность отмены и снятие резервов проверит сервер.')) return;
  saving.value = true; actionError.value = '';
  try {
    const result = await $fetch<any>(`/admin/orders/${encodeURIComponent(order.orderNumber)}/status`, { baseURL: config.public.apiBase, method: 'PATCH', headers: { Authorization: `Bearer ${token}` }, body: { status: target }, timeout: 35000 });
    if (session.token.value !== token || selected.value?.id !== order.id) return;
    if (!result || result.id !== order.id || result.status !== target) throw new Error('Invalid response');
    Object.assign(order, result); statusDraft.value = ''; savedOrder.value = { id: order.id, order: result };
  } catch (error: any) {
    if (session.token.value !== token || selected.value?.id !== order.id) return;
    const message = error?.data?.message;
    actionError.value = Array.isArray(message) ? message.join(' · ') : typeof message === 'string' ? message : 'Не удалось подтвердить изменение. Обновите заказ перед повторной попыткой: сервер уже мог принять запрос.';
  } finally { saving.value = false; }
}
let returnFocus: HTMLElement | null = null;
watch(() => Boolean(selected.value), async open => { if (open) { returnFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null; await nextTick(); document.querySelector<HTMLElement>('.order-drawer .close')?.focus(); } });
function close() { if (!saving.value && (!statusDraft.value || confirm('Закрыть карточку без изменения статуса?'))) { selected.value = null; nextTick(() => { if (returnFocus?.isConnected) returnFocus.focus(); }); } }
function keys(event: KeyboardEvent) {
  if (!selected.value) return;
  if (event.key === 'Escape') { event.preventDefault(); close(); }
  if (event.key !== 'Tab') return;
  const controls = Array.from(document.querySelectorAll<HTMLElement>('.order-drawer button:not(:disabled), .order-drawer select:not(:disabled), .order-drawer input:not(:disabled), .order-drawer a[href], .order-drawer textarea:not(:disabled)')).filter(el => el.getClientRects().length);
  const first = controls[0], last = controls[controls.length - 1];
  if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); }
  else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); }
}
onMounted(() => window.addEventListener('keydown', keys));
onBeforeUnmount(() => { window.removeEventListener('keydown', keys); selected.value = null; });
onBeforeRouteLeave(() => { if (saving.value) return false; if (selected.value && statusDraft.value && !confirm('Уйти без изменения статуса заказа?')) return false; selected.value = null; });
const statuses: Record<string, string> = { NEW: 'Новый', CONFIRMED: 'Подтверждён', PAID: 'Оплачен', ASSEMBLING: 'Сборка', SHIPPED: 'Отправлен', DELIVERED: 'Доставлен', CANCELLED: 'Отменён', REFUNDED: 'Возврат' };
const paymentNames: Record<string, string> = { PENDING: 'Ожидает оплаты', UNPAID: 'Не оплачен', PAID: 'Оплачен', SUCCEEDED: 'Оплачен', FAILED: 'Ошибка оплаты', CANCELED: 'Платёж отменён', CANCELLED: 'Платёж отменён', REFUNDED: 'Возвращена', PARTIALLY_REFUNDED: 'Частичный возврат' };
const reserveNames: Record<string, string> = { ACTIVE: 'Активен', CONSUMED: 'Использован', RELEASED: 'Снят', DIGITAL: 'Не требуется', LEGACY: 'Не подтверждён' };
const money = (value: any) => new Intl.NumberFormat('ru-RU', { style: 'currency', currency: selected.value?.currency || 'RUB' }).format(Number(value || 0));
const unitCount = computed(() => (selected.value?.items || []).reduce((sum: number, item: any) => sum + Number(item.quantity || 0), 0));
const countLabel = (value: number, forms: [string, string, string]) => `${value} ${forms[new Intl.PluralRules('ru').select(value) === 'one' ? 0 : new Intl.PluralRules('ru').select(value) === 'few' ? 1 : 2]}`;
const pickingCount = computed(() => warehouseTotal(selected.value, 'picked'));
const shippingCount = computed(() => warehouseTotal(selected.value, 'shipped'));
const reserveCount = computed(() => warehouseTotal(selected.value, 'reserved'));
const warehouse = computed(() => warehouseExecution(selected.value));
const warehouseCaption = computed(() => { const at = warehouseFactAt(selected.value); return at ? (warehouse.value?.isCurrent === false ? 'Исторические данные на ' : 'По данным 1С на ') + new Date(at).toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' }) : 'Подтверждённые данные 1С не получены'; });
const physicalOrder = computed(() => selected.value?.items?.some((item: any) => item.productType !== 'GIFT_CARD'));
const canOpenExecution = computed(() => physicalOrder.value && access.ready.value && access.can('oms.read'));
const executionRoute = computed(() => '/crm/fulfillment?order=' + encodeURIComponent(selected.value?.id || ''));
const address = computed(() => { const value = selected.value?.shippingAddress; if (!value) return 'Адрес доставки не указан'; if (typeof value === 'string') return value; return Object.values(value).filter(Boolean).join(', '); });
async function copyNumber() { if (!selected.value) return; await navigator.clipboard?.writeText(selected.value.orderNumber); copied.value = true; setTimeout(() => copied.value = false, 1600); }
</script>
<template>
  <Teleport v-if="selected && isCrmOrder" to="body"><aside class="order-backdrop admin-dialog-backdrop crm-order-webbackdrop" @click.self="close">
    <section class="order-drawer admin-dialog admin-dialog--drawer crm-approved-order crm-order-webdrawer" role="dialog" aria-modal="true" aria-labelledby="web-order-title">
      <header class="drawer-header admin-dialog-head crm-order-webdrawer-header"><div class="crm-order-title-line"><h2 id="web-order-title">Заказ {{ selected.orderNumber }}</h2><button class="crm-button crm-button--icon" type="button" @click="copyNumber" :title="copied ? 'Номер скопирован' : 'Скопировать номер заказа'" :aria-label="copied ? 'Номер скопирован' : 'Скопировать номер заказа'"><Check v-if="copied" :size="16" /><Copy v-else :size="16" /></button><span class="crm-badge" :data-status="selected.status">{{ statuses[selected.status] || selected.status }}</span></div><button type="button" class="close crm-button crm-button--icon" :disabled="saving" aria-label="Закрыть карточку заказа" @click="close"><X :size="20" /></button></header>
      <div class="drawer-body admin-dialog-body crm-order-webdrawer-body">
        <div class="crm-order-identity"><div><strong class="crm-order-company">{{ [selected.user?.firstName, selected.user?.lastName].filter(Boolean).join(' ') || selected.buyerName || 'Гостевой заказ' }}</strong><p class="crm-order-meta">Интернет-магазин <span>·</span> {{ new Date(selected.createdAt).toLocaleString('ru-RU') }}</p></div><div class="crm-order-total"><span>Сумма заказа</span><strong>{{ money(selected.finalAmount) }}</strong></div></div>
        <div class="crm-order-stages" aria-label="Состояния заказа"><div><span>Оплата</span><strong :data-tone="['PAID', 'SUCCEEDED'].includes(selected.paymentStatus) ? 'success' : 'neutral'">{{ paymentNames[selected.paymentStatus] || 'Нет подтверждения' }}</strong><small>Статус платёжной системы</small></div><div><span>Резерв</span><strong>{{ !physicalOrder ? 'Не требуется' : reserveCount == null ? 'Нет данных 1С' : warehouseNumber(reserveCount) + ' ед.' }}</strong><small>{{ !physicalOrder ? 'Электронный заказ' : warehouseCaption }}</small></div><div><span>Сборка</span><strong>{{ !physicalOrder ? 'Не требуется' : pickingCount == null ? 'Нет данных 1С' : pickingCount + ' из ' + unitCount + ' единиц' }}</strong><small>{{ !physicalOrder ? 'Электронный заказ' : warehouseCaption }}</small></div><div><span>Отгрузка</span><strong>{{ !physicalOrder ? 'Электронная доставка' : shippingCount == null ? 'Нет данных 1С' : shippingCount + ' из ' + unitCount + ' единиц' }}</strong><small>{{ selected.trackingNumber ? 'Трек: ' + selected.trackingNumber : 'Трек-номер не указан' }}</small></div></div>
        <div class="crm-order-workspace"><div class="crm-order-primary">
          <div v-if="canOpenExecution" class="crm-order-next-action"><div><h2>Исполнение на складе 1С</h2><p>Проверьте подтверждённый резерв, ход отбора и документы отгрузки. Складские операции выполняются в 1С.</p></div><NuxtLink class="crm-button crm-button--primary" :to="executionRoute">Монитор склада 1С<ArrowRight :size="17" /></NuxtLink></div>
          <section class="crm-order-table-panel"><div class="crm-order-section-heading"><h2>Состав заказа</h2><span>{{ selected.items?.length || 0 }} позиций · {{ unitCount }} единиц</span></div><div class="crm-order-table-scroll"><table class="crm-order-items-table"><thead><tr><th scope="col">Товар</th><th scope="col">Шт.</th><th scope="col">Цена за шт.</th><th scope="col">Сумма</th></tr></thead><tbody><tr v-for="item in selected.items" :key="item.id"><td><strong>{{ item.productName }}</strong><small>{{ [item.variantName, item.variant?.sku || item.externalSku].filter(Boolean).join(' · ') }}</small></td><td data-label="Количество">{{ item.quantity }}</td><td data-label="Цена за шт.">{{ money(item.price) }}</td><td data-label="Сумма"><strong>{{ money(item.total) }}</strong></td></tr></tbody></table></div><p v-if="!selected.items?.length" class="crm-order-empty">Состав не указан.</p><div class="crm-order-calculation"><p>Суммы и условия — из заказа интернет-магазина.</p><dl><div v-if="selected.totalAmount != null"><dt>Сумма товаров</dt><dd>{{ money(selected.totalAmount) }}</dd></div><div v-if="Number(selected.discountAmount) > 0"><dt>Скидка</dt><dd>−{{ money(selected.discountAmount) }}</dd></div><div v-if="selected.shippingCost != null"><dt>Доставка</dt><dd>{{ money(selected.shippingCost) }}</dd></div><div class="crm-order-calculation-total"><dt>Итого по заказу</dt><dd>{{ money(selected.finalAmount) }}</dd></div></dl></div></section>
          <section class="crm-order-delivery" aria-label="Клиент и доставка"><div><h2><Phone :size="16" />Получатель</h2><strong>{{ [selected.user?.firstName, selected.user?.lastName].filter(Boolean).join(' ') || selected.buyerName || 'Гость' }}</strong><span>{{ selected.user?.email || selected.buyerEmail || 'Email не указан' }}</span><span>{{ selected.user?.phone || selected.buyerPhone || 'Телефон не указан' }}</span></div><div><h2><MapPin :size="16" />Доставка</h2><strong>{{ selected.shippingProvider || 'Способ не указан' }}</strong><span>{{ address }}</span><span v-if="selected.trackingNumber">Трек: {{ selected.trackingNumber }}</span></div></section>
        </div><aside class="crm-order-context"><section class="crm-order-sync" :data-confirmed="selected.isSynced1C"><div><h2>Обмен с 1С</h2><span class="crm-order-state" :data-tone="selected.oneCSyncError ? 'warning' : selected.isSynced1C ? 'success' : 'warning'">{{ selected.oneCSyncError ? 'Ошибка передачи' : selected.isSynced1C ? 'Подтверждён' : 'Не подтверждён' }}</span></div><p>{{ selected.oneCSyncError || (selected.oneCSyncAt ? 'Последнее подтверждение: ' + new Date(selected.oneCSyncAt).toLocaleString('ru-RU') : 'Подтверждение передачи ещё не получено.') }}</p></section><section class="crm-order-recent"><h2>История заказа</h2><ol class="crm-order-timeline"><li v-for="entry in selected.history" :key="entry.id"><time>{{ new Date(entry.createdAt).toLocaleString('ru-RU') }}</time><div><strong>{{ statuses[entry.toStatus] || entry.toStatus }}</strong><p v-if="entry.comment">{{ entry.comment }}</p></div></li></ol><p v-if="!selected.history?.length" class="crm-order-muted">История пока пуста.</p></section></aside></div>
      </div>
      <footer v-if="nextStatuses.length || actionError" class="crm-order-webdrawer-footer"><p v-if="actionError" class="crm-order-notice crm-order-notice--danger" role="alert">{{ actionError }}</p><div v-if="nextStatuses.length" class="studio-order-actions"><label>Изменить статус заказа<select class="crm-input" v-model="statusDraft" :disabled="saving"><option value="">Выберите действие</option><option v-for="status in nextStatuses" :key="status" :value="status">{{ statuses[status] }}</option></select></label><button type="button" class="studio-order-save crm-button crm-button--primary" :disabled="saving || !statusDraft" @click="saveStatus">{{ saving ? 'Сохраняем…' : 'Изменить статус' }}</button></div></footer>
    </section>
  </aside></Teleport>

  <!-- The storefront administration retains its original drawer and permissions. -->
  <aside data-v-ui-3f69e94afb94 v-else-if="selected" class="order-backdrop admin-dialog-backdrop" @click.self="close"><section data-v-ui-3f69e94afb94 class="order-drawer admin-dialog admin-dialog--drawer" role="dialog" aria-modal="true" aria-label="Карточка заказа"><header data-v-ui-3f69e94afb94 class="drawer-header admin-dialog-head"><div data-v-ui-3f69e94afb94><p data-v-ui-3f69e94afb94 class="eyebrow">ЗАКАЗ МАГАЗИНА</p><div data-v-ui-3f69e94afb94 class="number-line"><h2 data-v-ui-3f69e94afb94>{{ selected.orderNumber }}</h2><button class="crm-button" data-v-ui-3f69e94afb94 @click="copyNumber" title="Скопировать номер"><Check data-v-ui-3f69e94afb94 v-if="copied" :size="15" /><Copy data-v-ui-3f69e94afb94 v-else :size="15" /></button></div><span data-v-ui-3f69e94afb94>{{ new Date(selected.createdAt).toLocaleString('ru-RU') }}</span></div><button data-v-ui-3f69e94afb94 type="button" class="close crm-button crm-button--icon" :disabled="saving" aria-label="Закрыть карточку заказа" @click="close"><X data-v-ui-3f69e94afb94 :size="19" /></button></header><div data-v-ui-3f69e94afb94 class="drawer-body admin-dialog-body"><div data-v-ui-3f69e94afb94 class="order-summary"><div data-v-ui-3f69e94afb94><span data-v-ui-3f69e94afb94>Статус</span><strong data-v-ui-3f69e94afb94 :class="`status-${selected.status.toLowerCase()}`">{{ statuses[selected.status] || selected.status }}</strong></div><div data-v-ui-3f69e94afb94><span data-v-ui-3f69e94afb94>Оплата</span><strong data-v-ui-3f69e94afb94>{{ statuses[selected.paymentStatus] || selected.paymentStatus }}</strong></div><div data-v-ui-3f69e94afb94><span data-v-ui-3f69e94afb94>Итого</span><strong data-v-ui-3f69e94afb94>{{ Number(selected.finalAmount || 0).toLocaleString('ru-RU') }} ₽</strong></div></div><section data-v-ui-3f69e94afb94 class="detail-section"><h3 data-v-ui-3f69e94afb94><Package data-v-ui-3f69e94afb94 :size="16" /> Состав заказа</h3><div data-v-ui-3f69e94afb94 v-for="item in selected.items" :key="item.id" class="item"><div data-v-ui-3f69e94afb94><strong data-v-ui-3f69e94afb94>{{ item.productName }}</strong><small data-v-ui-3f69e94afb94>{{ item.variantName }} · {{ item.quantity }} шт.</small></div><span data-v-ui-3f69e94afb94>{{ Number(item.total || 0).toLocaleString('ru-RU') }} ₽</span></div><p data-v-ui-3f69e94afb94 v-if="!selected.items?.length" class="muted">Состав не указан</p></section><section data-v-ui-3f69e94afb94 class="detail-section"><h3 data-v-ui-3f69e94afb94><Phone data-v-ui-3f69e94afb94 :size="16" /> Клиент</h3><div data-v-ui-3f69e94afb94 class="client"><strong data-v-ui-3f69e94afb94>{{ [selected.user?.firstName, selected.user?.lastName].filter(Boolean).join(' ') || 'Гость' }}</strong><span data-v-ui-3f69e94afb94>{{ selected.user?.email || 'Email не указан' }}</span><span data-v-ui-3f69e94afb94>{{ selected.user?.phone || 'Телефон не указан' }}</span></div></section><section data-v-ui-3f69e94afb94 class="detail-section"><h3 data-v-ui-3f69e94afb94><MapPin data-v-ui-3f69e94afb94 :size="16" /> Доставка</h3><p data-v-ui-3f69e94afb94 class="address">{{ address }}</p><p data-v-ui-3f69e94afb94 v-if="selected.shippingProvider || selected.trackingNumber" class="delivery-meta">{{ selected.shippingProvider || 'Служба доставки' }} <b data-v-ui-3f69e94afb94 v-if="selected.trackingNumber">· {{ selected.trackingNumber }}</b></p></section><section data-v-ui-3f69e94afb94 class="detail-section history"><h3 data-v-ui-3f69e94afb94>История статусов</h3><div data-v-ui-3f69e94afb94 v-for="entry in selected.history" :key="entry.id" class="history-row"><i data-v-ui-3f69e94afb94></i><div data-v-ui-3f69e94afb94><strong data-v-ui-3f69e94afb94>{{ statuses[entry.toStatus] || entry.toStatus }}</strong><small data-v-ui-3f69e94afb94>{{ new Date(entry.createdAt).toLocaleString('ru-RU') }}<template v-if="entry.comment"> · {{ entry.comment }}</template></small></div></div><p data-v-ui-3f69e94afb94 v-if="!selected.history?.length" class="muted">История пока пуста</p></section></div><p data-v-ui-3f69e94afb94 v-if="actionError" class="studio-order-action-error" role="alert">{{ actionError }}</p><footer data-v-ui-3f69e94afb94 v-if="nextStatuses.length" class="studio-order-actions"><label data-v-ui-3f69e94afb94>Следующий этап<select class="crm-input" data-v-ui-3f69e94afb94 v-model="statusDraft" :disabled="saving"><option data-v-ui-3f69e94afb94 value="">Выберите действие</option><option data-v-ui-3f69e94afb94 v-for="status in nextStatuses" :key="status" :value="status">{{ statuses[status] }}</option></select></label><button data-v-ui-3f69e94afb94 type="button" class="studio-order-save crm-button" :disabled="saving || !statusDraft" @click="saveStatus">{{ saving ? 'Сохраняем…' : 'Изменить статус' }}</button></footer></section></aside>
</template>
